import { test, expect } from '@playwright/test';

test.describe('Dashboard Sidebar to Bottom Nav Responsive', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
    await page.waitForLoadState('networkidle');
  });

  test('should display sidebar on desktop viewport', async ({ page }) => {
    await page.setViewportSize({ width: 1920, height: 1080 });

    const sidebar = page.getByRole('navigation', { name: /sidebar|main navigation/i });
    await expect(sidebar).toBeVisible();

    const sidebarBox = await sidebar.boundingBox();
    expect(sidebarBox?.width).toBeGreaterThan(200);

    const navItems = page.getByRole('link').filter({ has: page.locator('[class*="nav"]') });
    const itemCount = await navItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });

  test('should hide sidebar and show bottom nav on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const sidebar = page.getByRole('navigation', { name: /sidebar|main navigation/i });
    await expect(sidebar).not.toBeVisible();

    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });
    await expect(bottomNav).toBeVisible();

    const bottomNavBox = await bottomNav.boundingBox();
    expect(bottomNavBox?.y).toBeGreaterThan(600);
  });

  test('should maintain navigation functionality in bottom nav on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });
    await expect(bottomNav).toBeVisible();

    const navLinks = bottomNav.getByRole('link');
    const linkCount = await navLinks.count();
    expect(linkCount).toBeGreaterThan(0);

    const firstLink = navLinks.first();
    await expect(firstLink).toBeVisible();
    await expect(firstLink).toHaveAttribute('href', /.+/);
  });

  test('should position bottom nav at bottom of viewport on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });
    const bottomNavBox = await bottomNav.boundingBox();

    expect(bottomNavBox).not.toBeNull();
    if (bottomNavBox) {
      const viewportHeight = 667;
      const navBottom = bottomNavBox.y + bottomNavBox.height;
      expect(navBottom).toBeCloseTo(viewportHeight, 10);
    }
  });

  test('should transition from sidebar to bottom nav at tablet breakpoint', async ({ page }) => {
    await page.setViewportSize({ width: 1024, height: 768 });

    const sidebar = page.getByRole('navigation', { name: /sidebar|main navigation/i });
    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });

    await expect(sidebar).toBeVisible();
    await expect(bottomNav).not.toBeVisible();

    await page.setViewportSize({ width: 375, height: 667 });

    await expect(sidebar).not.toBeVisible();
    await expect(bottomNav).toBeVisible();
  });

  test('should have proper spacing and not overlap content in bottom nav', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const mainContent = page.getByRole('main');
    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });

    const contentBox = await mainContent.boundingBox();
    const navBox = await bottomNav.boundingBox();

    expect(contentBox).not.toBeNull();
    expect(navBox).not.toBeNull();

    if (contentBox && navBox) {
      const contentBottom = contentBox.y + contentBox.height;
      expect(contentBottom).toBeLessThanOrEqual(navBox.y);
    }
  });

  test('should display all navigation items in bottom nav on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });
    const navItems = bottomNav.getByRole('link');

    const itemCount = await navItems.count();
    expect(itemCount).toBeGreaterThan(2);

    for (let i = 0; i < itemCount; i++) {
      const item = navItems.nth(i);
      await expect(item).toBeVisible();
    }
  });

  test('should maintain active state indicator in bottom nav', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });
    const activeLink = bottomNav.getByRole('link', { current: 'page' });

    const activeCount = await activeLink.count();
    expect(activeCount).toBeGreaterThanOrEqual(0);

    if (activeCount > 0) {
      await expect(activeLink.first()).toHaveAttribute('aria-current', 'page');
    }
  });

  test('should handle bottom nav navigation without page reload on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const bottomNav = page.getByRole('navigation', { name: /bottom|mobile|footer navigation/i });
    const navLinks = bottomNav.getByRole('link');

    const firstLink = navLinks.first();
    const href = await firstLink.getAttribute('href');

    if (href && !href.startsWith('http')) {
      await firstLink.click();
      await page.waitForLoadState('networkidle');

      const currentUrl = page.url();
      expect(currentUrl).toContain(href);
    }
  });
});
